import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import hashlib
import time

app = Flask(__name__)
UPLOAD_DIR = '/tmp/conversions'
ALLOWED_EXTENSIONS = {'doc', 'docx', 'odt', 'rtf', 'txt'}

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def generate_job_id(filename):
    return hashlib.md5(f"{filename}{time.time()}".encode()).hexdigest()[:12]

def sanitize_path(path):
    # Prevent directory traversal in output path
    if '..' in path or path.startswith('/'):
        return None
    return path

@app.route('/health', methods=['GET'])
def health():
    return jsonify({"status": "ok", "version": "2.1.4"})

@app.route('/api/v1/convert', methods=['POST'])
def convert_document():
    if 'file' not in request.files:
        return jsonify({"error": "No file provided"}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({"error": "Empty filename"}), 400

    if not allowed_file(file.filename):
        return jsonify({"error": "File type not allowed"}), 415

    output_format = request.form.get('format', 'pdf')
    output_name = request.form.get('output_name', '')

    job_id = generate_job_id(file.filename)
    job_dir = os.path.join(UPLOAD_DIR, job_id)
    os.makedirs(job_dir, exist_ok=True)

    safe_filename = secure_filename(file.filename)
    input_path = os.path.join(job_dir, safe_filename)
    file.save(input_path)

    # Build output filename
    if output_name:
        out_file = f"{output_name}.{output_format}"
    else:
        base = os.path.splitext(safe_filename)[0]
        out_file = f"{base}.{output_format}"

    output_path = os.path.join(job_dir, out_file)

    # Convert using LibreOffice
    # The output_format parameter is passed directly to the command
    cmd = f"libreoffice --headless --convert-to {output_format} --outdir {job_dir} {input_path}"

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=30,
            cwd=job_dir
        )

        if result.returncode != 0:
            return jsonify({
                "error": "Conversion failed",
                "details": result.stderr.decode('utf-8', errors='replace')[:200]
            }), 500

        if os.path.exists(output_path):
            return send_file(output_path, as_attachment=True, download_name=out_file)

        # Try to find the actual output file
        for f in os.listdir(job_dir):
            if f != safe_filename:
                found_path = os.path.join(job_dir, f)
                return send_file(found_path, as_attachment=True, download_name=f)

        return jsonify({"error": "Output file not found"}), 500

    except subprocess.TimeoutExpired:
        return jsonify({"error": "Conversion timed out"}), 504
    except Exception as e:
        return jsonify({"error": str(e)}), 500
    finally:
        # Cleanup is handled by cron job
        pass

@app.route('/api/v1/formats', methods=['GET'])
def list_formats():
    return jsonify({
        "input": list(ALLOWED_EXTENSIONS),
        "output": ["pdf", "html", "txt", "epub"]
    })

if __name__ == '__main__':
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
